/**
 * Настройки симуляции. Значения по умолчанию воспроизводят эталон, кроме явно помеченных дополнений.
 */
export type SimulationConfig = {
  /**
   * ДОПОЛНЕНИЕ (в эталоне нет): блокировка вращения — фаза «release» не завершается, пока в красной зоне
   * есть люди без разрешения сценария; помбуры уходят от устья, как только клинья извлечены (t > 1.2 с).
   * false — точное поведение эталона (в начале бурения помбуры ещё ~1.7 с у вращающейся колонны).
   */
  rotationInterlock: boolean;
  /**
   * ДОПОЛНЕНИЕ: в эталоне стол ротора неподвижен (бурение верхним приводом).
   * true — стол ротора вращается вместе с колонной, когда колонна не на клиньях.
   */
  rotaryTableFollowsString: boolean;
  /** эталон: «Система раннего обнаружения ГНВП» (по умолчанию включена) */
  earlyKickDetection: boolean;
  /** эталон: «Полный цикл: бурение → обсадка → переезд» */
  auto: boolean;
  /** максимальный шаг интегрирования, с (эталон: dt ≤ 0.05 с) */
  maxStep: number;
};

export const DEFAULT_CONFIG: SimulationConfig = {
  rotationInterlock: true,
  rotaryTableFollowsString: true,
  earlyKickDetection: true,
  auto: true,
  maxStep: 0.05,
};
